  class WxStderrLogTargetRuntime final : public WxLogTargetRuntime
  {
  public:
    explicit WxStderrLogTargetRuntime(FILE* const stream) noexcept
      : m_stream(stream != nullptr ? stream : stderr)
    {
    }

    void Slot00() override {}
    void Slot04() override {}

    int LogRecordWithTimestamp(
      const int logLevel,
      const wchar_t* const messageText,
      const std::uint32_t timestampLow,
      const std::uint32_t timestampHigh
    ) override
    {
      (void)timestampLow;
      (void)timestampHigh;

      if (messageText != nullptr && m_stream != nullptr) {
        (void)std::fwprintf(m_stream, L"[wx:%d] %ls\n", logLevel, messageText);
        (void)std::fflush(m_stream);
      }
      return 0;
    }

  private:
    FILE* m_stream = nullptr; // +0x04
  };

