  [[nodiscard]] std::int32_t wxMapCharsetToEncodingRuntime(
    const std::int32_t charset
  ) noexcept
  {
    if (charset > 255) {
      return -1;
    }

    if (charset == 255) {
      return 20;
    }

    switch (charset) {
    case 0:
      return 32;
    case 128:
      return 26;
    case 129:
      return 28;
    case 134:
      return 27;
    case 136:
      return 29;
    case 161:
      return 33;
    case 162:
      return 34;
    case 177:
      return 35;
    case 178:
      return 36;
    case 186:
      return 37;
    case 204:
      return 31;
    case 222:
      return 20;
    case 238:
      return 30;
    default:
      return -1;
    }
  }

  [[nodiscard]] std::vector<std::wstring> SplitNativeFontDescriptionTokens(
    const std::wstring& description
  )
  {
    std::vector<std::wstring> tokens{};
    std::wstring token{};

    auto flushToken = [&]() {
      if (!token.empty()) {
        tokens.push_back(token);
        token.clear();
      }
    };

    for (const wchar_t ch : description) {
      const bool isSeparator = ch == L';' || ch == L',' || std::iswspace(static_cast<wint_t>(ch)) != 0;
      if (isSeparator) {
        flushToken();
      } else {
        token.push_back(ch);
      }
    }
    flushToken();
    return tokens;
  }

