/**
 * Address: 0x00979280 (FUN_00979280)
 *
 * What it does:
 * Matches one mouse-event double-click selector lane (`-1/1/2/3`) against
 * event type lane `+0x0C` using left/middle/right-dclick wx event constants.
 */
bool wxMouseEventMatchesDoubleClickSelectorRuntime_Impl(
  const void* const mouseEventRuntime,
  const std::int32_t selector
) noexcept
{
  struct WxMouseEventTypeRuntimeView
  {
    std::uint8_t lanes00_0B[0x0C]{};
    std::int32_t eventType = 0; // +0x0C
  };
  static_assert(
    offsetof(WxMouseEventTypeRuntimeView, eventType) == 0x0C,
    "WxMouseEventTypeRuntimeView::eventType offset must be 0x0C"
  );

  const auto* const eventView = static_cast<const WxMouseEventTypeRuntimeView*>(mouseEventRuntime);
  if (eventView == nullptr) {
    return false;
  }

  const std::int32_t eventType = eventView->eventType;
  // Runtime-assigned ids - see the note in the press selector below.
  const std::int32_t leftDClickType = *WxEventTypeSlot(gWxEvtLeftDClickRuntimeType);
  const std::int32_t middleDClickType = *WxEventTypeSlot(gWxEvtMiddleDClickRuntimeType);
  const std::int32_t rightDClickType = *WxEventTypeSlot(gWxEvtRightDClickRuntimeType);

  switch (selector) {
    case -1:
      return eventType == leftDClickType || eventType == middleDClickType || eventType == rightDClickType;
    case 1:
      return eventType == leftDClickType;
    case 2:
      return eventType == middleDClickType;
    case 3:
      return eventType == rightDClickType;
    default:
      return false;
  }
}

/**
 * Address: 0x00979310 (FUN_00979310)
 *
 * What it does:
 * Matches one mouse-event press selector lane (`-1/1/2/3`) against event
 * type lane `+0x0C` using left/middle/right-down wx event constants.
 */
bool wxMouseEventMatchesPressSelectorRuntime_Impl(
  const void* const mouseEventRuntime,
  const std::int32_t selector
) noexcept
{
  struct WxMouseEventTypeRuntimeView
  {
    std::uint8_t lanes00_0B[0x0C]{};
    std::int32_t eventType = 0; // +0x0C
  };
  static_assert(
    offsetof(WxMouseEventTypeRuntimeView, eventType) == 0x0C,
    "WxMouseEventTypeRuntimeView::eventType offset must be 0x0C"
  );

  const auto* const eventView = static_cast<const WxMouseEventTypeRuntimeView*>(mouseEventRuntime);
  if (eventView == nullptr) {
    return false;
  }

  const std::int32_t eventType = eventView->eventType;
  // Against the runtime-assigned ids, not the wx 2.4.2 compile-time numbering:
  // this build hands out event types from wxNewEventType() at startup, so the
  // events actually raised here carry ids from that sequence and never the
  // 1100/1110/1120 the header constants name. Comparing against the constants
  // made every button test fail - the pointer still moved controls, because
  // motion is matched through WX_GetWxEvtMotionType(), but no click ever
  // became a press.
  const std::int32_t leftDownType = *WxEventTypeSlot(gWxEvtLeftDownRuntimeType);
  const std::int32_t middleDownType = *WxEventTypeSlot(gWxEvtMiddleDownRuntimeType);
  const std::int32_t rightDownType = *WxEventTypeSlot(gWxEvtRightDownRuntimeType);

  switch (selector) {
    case -1:
      return eventType == leftDownType || eventType == middleDownType || eventType == rightDownType;
    case 1:
      return eventType == leftDownType;
    case 2:
      return eventType == middleDownType;
    case 3:
      return eventType == rightDownType;
    default:
      return false;
  }
}

