  int WxRegistryRootIndexFromHandle(const HKEY rootKey) noexcept
  {
    static const std::array<HKEY, 7> kRootKeyTable{
      HKEY_CLASSES_ROOT,
      HKEY_CURRENT_USER,
      HKEY_LOCAL_MACHINE,
      HKEY_USERS,
      HKEY_CURRENT_CONFIG,
      nullptr,
      nullptr
    };

    for (std::size_t index = 0; index < kRootKeyTable.size(); ++index) {
      if (kRootKeyTable[index] == rootKey) {
        return static_cast<int>(index);
      }
    }

    return 0;
  }

  [[nodiscard]] const wchar_t* WxRegistryRootDisplayName(
    const HKEY rootKey,
    const bool shortName
  ) noexcept
  {
    static constexpr std::array<const wchar_t*, 7> kShortNames{
      L"HKCR",
      L"HKCU",
      L"HKLM",
      L"HKU",
      L"HKCC",
      L"HK?",
      L"HK?"
    };
    static constexpr std::array<const wchar_t*, 7> kLongNames{
      L"HKEY_CLASSES_ROOT",
      L"HKEY_CURRENT_USER",
      L"HKEY_LOCAL_MACHINE",
      L"HKEY_USERS",
      L"HKEY_CURRENT_CONFIG",
      L"HKEY_UNKNOWN",
      L"HKEY_UNKNOWN"
    };

    const int rootIndex = WxRegistryRootIndexFromHandle(rootKey);
    if (rootIndex == 0 && rootKey != HKEY_CLASSES_ROOT) {
      return shortName ? L"HK?" : L"HKEY_UNKNOWN";
    }

    return shortName ? kShortNames[static_cast<std::size_t>(rootIndex)] : kLongNames[static_cast<std::size_t>(rootIndex)];
  }

