wxWindowBase* wxWindowMswRuntime::GetParentWindow() const
{
  const WxWindowBaseRuntimeState* const state = FindWxWindowBaseRuntimeState(this);
  return (state != nullptr) ? state->parentWindow : nullptr;
}

