/**
 * Address: 0x00A8F5C6 (FUN_00A8F5C6)
 *
 * What it does:
 * Compares up to `characterCount` UTF-16 code units and returns the first
 * unsigned difference, matching wide `strncmp` semantics.
 */
std::int32_t wxCompareWidePrefixRuntime(
  const wchar_t* left,
  const wchar_t* right,
  std::int32_t characterCount
) noexcept
{
  if (characterCount == 0)
  {
    return 0;
  }

  while (--characterCount > 0 && *left != L'\0' && *left == *right)
  {
    ++left;
    ++right;
  }

  return static_cast<std::uint16_t>(*left) - static_cast<std::uint16_t>(*right);
}


