  static_assert(sizeof(WxLegacySharedStringHeaderRuntimeView) == 0x0C, "WxLegacySharedStringHeaderRuntimeView size must be 0x0C");


  void ReleaseLegacySharedStringPayloadAndResetRuntime(
    wxStringRuntime* const value
  ) noexcept
  {
    if (value == nullptr || value->m_pchData == nullptr) {
      return;
    }

    if (value->m_pchData != wxEmptyString) {
      auto* const header =
        reinterpret_cast<WxLegacySharedStringHeaderRuntimeView*>(reinterpret_cast<std::int32_t*>(value->m_pchData) - 3);
      if (header->refCount != -1) {
        --header->refCount;
        if (header->refCount == 0) {
          ::operator delete(header);
        }
      }
    }

    value->m_pchData = const_cast<wchar_t*>(wxEmptyString);
  }


