/**
 * Address: 0x00960B60 (FUN_00960B60)
 *
 * What it does:
 * Assigns one UTF-16 span into a wx-string lane; when `charCount==0`, it
 * releases the previous shared payload and resets to `wxEmptyString`.
 */
bool wxAssignWideSpanToRuntimeString(
  wxStringRuntime* const outText,
  const std::size_t charCount,
  const wchar_t* const sourceText
) noexcept
{
  if (outText == nullptr) {
    return false;
  }

  if (charCount == 0u) {
    ReleaseLegacySharedStringPayloadAndResetRuntime(outText);
    return true;
  }

  if (sourceText == nullptr) {
    return false;
  }

  const std::size_t payloadBytes =
    sizeof(WxLegacySharedStringHeaderRuntimeView) + (charCount + 1u) * sizeof(wchar_t);
  auto* const raw = static_cast<std::uint8_t*>(::operator new(payloadBytes, std::nothrow));
  if (raw == nullptr) {
    return false;
  }

  auto* const header = reinterpret_cast<WxLegacySharedStringHeaderRuntimeView*>(raw);
  header->refCount = 1;
  header->length = static_cast<std::int32_t>(charCount);
  header->capacity = static_cast<std::int32_t>(charCount);

  auto* const text = reinterpret_cast<wchar_t*>(raw + sizeof(WxLegacySharedStringHeaderRuntimeView));
  std::memcpy(text, sourceText, charCount * sizeof(wchar_t));
  text[charCount] = L'\0';

  ReleaseLegacySharedStringPayloadAndResetRuntime(outText);
  outText->m_pchData = text;
  return true;
}


wxStringRuntime* WxStringRuntimeOps::Empty(
  wxStringRuntime* const value,
  const std::uint32_t newLength
)
{
  return value != nullptr ? value->Empty(newLength) : nullptr;
}

wxStringRuntime* WxStringRuntimeOps::InitWith(
  wxStringRuntime* const outValue,
  const wchar_t* const sourceText,
  const std::int32_t beginOffset,
  const std::int32_t lengthHint
)
{
  if (outValue == nullptr) {
    return nullptr;
  }

  const wchar_t* const source = sourceText != nullptr ? sourceText : wxEmptyString;
  const std::size_t sourceLength = std::wcslen(source);
  std::size_t startOffset = 0u;
  if (beginOffset > 0) {
    startOffset = static_cast<std::size_t>(beginOffset);
    if (startOffset > sourceLength) {
      startOffset = sourceLength;
    }
  }

  const wchar_t* const start = source + startOffset;
  const std::size_t remaining = sourceLength - startOffset;
  std::size_t charCount = remaining;
  if (lengthHint != -101) {
    if (lengthHint <= 0) {
      charCount = 0u;
    } else {
      const std::size_t requested = static_cast<std::size_t>(lengthHint);
      charCount = (requested < remaining) ? requested : remaining;
    }
  }

  (void)wxAssignWideSpanToRuntimeString(outValue, charCount, start);
  return outValue;
}

wxStringRuntime* WxStringRuntimeOps::append(
  wxStringRuntime* const outValue,
  const std::int32_t lengthHint,
  const wchar_t* const sourceText
)
{
  if (outValue == nullptr || sourceText == nullptr) {
    return outValue;
  }

  std::size_t appendLength = 0u;
  if (lengthHint == -101) {
    appendLength = std::wcslen(sourceText);
  } else if (lengthHint > 0) {
    appendLength = static_cast<std::size_t>(lengthHint);
  }

  if (appendLength == 0u) {
    return outValue;
  }

  std::wstring mergedText = std::wstring(outValue->c_str());
  mergedText.append(sourceText, sourceText + appendLength);
  (void)wxAssignWideSpanToRuntimeString(outValue, mergedText.size(), mergedText.c_str());
  return outValue;
}


