  [[nodiscard]] std::int32_t WxSharedWideStringLengthFromHeader(
    const wchar_t* const text
  ) noexcept
  {
    if (text == nullptr) {
      return 0;
    }

    return *(reinterpret_cast<const std::int32_t*>(text) - 2);
  }


  /**
   * Address: 0x00961AE0 (FUN_00961AE0)
   *
   * What it does:
   * Initializes output string from one shared source-text lane (or empty when
   * source length is zero), then appends one shared UTF-16 suffix lane using
   * the suffix header-length field.
   */
  wxStringRuntime* wxStringCopySharedPrefixAndAppendSharedSuffix(
    wxStringRuntime* const outText,
    const wchar_t* const* const sourceTextStorage,
    const wchar_t* const* const appendTextStorage
  )
  {
    if (outText == nullptr) {
      return nullptr;
    }

    outText->m_pchData = nullptr;

    const wchar_t* sourceText = wxEmptyString;
    if (sourceTextStorage != nullptr && *sourceTextStorage != nullptr) {
      const wchar_t* const candidate = *sourceTextStorage;
      const auto* const header = reinterpret_cast<const std::int32_t*>(candidate) - 3;
      sourceText = (header[1] != 0) ? candidate : wxEmptyString;
    }

    std::wstring merged(sourceText);
    if (appendTextStorage != nullptr && *appendTextStorage != nullptr) {
      const wchar_t* const appendText = *appendTextStorage;
      const std::int32_t appendLength = WxSharedWideStringLengthFromHeader(appendText);
      if (appendLength > 0) {
        merged.append(appendText, appendText + appendLength);
      }
    }

    AssignOwnedWxString(outText, merged);
    return outText;
  }


