/**
 * Address: 0x009C8AE0 (FUN_009C8AE0)
 *
 * What it does:
 * Applies one pending text/background color state onto the host DC lane and
 * switches the host DC to transparent text background mode.
 */
void wxApplyPendingDcTextColorsRuntime(
  void* colorStateRuntime
) noexcept
{
  struct WxDcColorHostRuntimeView
  {
    std::byte lane00_FB[0xFC]{};
    HDC mDeviceContext = nullptr; // +0xFC
  };
  static_assert(
    offsetof(WxDcColorHostRuntimeView, mDeviceContext) == 0xFC,
    "WxDcColorHostRuntimeView::mDeviceContext offset must be 0xFC"
  );

  struct WxDcColorStateRuntimeView
  {
    WxDcColorHostRuntimeView* mHostRuntime = nullptr; // +0x00
    COLORREF mTextColor = 0;                          // +0x04
    COLORREF mBackgroundColor = 0;                    // +0x08
    std::uint8_t mApplyColors = 0;                    // +0x0C
  };
  static_assert(
    offsetof(WxDcColorStateRuntimeView, mHostRuntime) == 0x00,
    "WxDcColorStateRuntimeView::mHostRuntime offset must be 0x00"
  );
  static_assert(
    offsetof(WxDcColorStateRuntimeView, mTextColor) == 0x04,
    "WxDcColorStateRuntimeView::mTextColor offset must be 0x04"
  );
  static_assert(
    offsetof(WxDcColorStateRuntimeView, mBackgroundColor) == 0x08,
    "WxDcColorStateRuntimeView::mBackgroundColor offset must be 0x08"
  );
  static_assert(
    offsetof(WxDcColorStateRuntimeView, mApplyColors) == 0x0C,
    "WxDcColorStateRuntimeView::mApplyColors offset must be 0x0C"
  );

  auto* const colorState = static_cast<WxDcColorStateRuntimeView*>(colorStateRuntime);
  if (colorState == nullptr || colorState->mApplyColors == 0u) {
    return;
  }

  HDC const deviceContext = colorState->mHostRuntime->mDeviceContext;
  (void)::SetBkMode(deviceContext, TRANSPARENT);
  (void)::SetTextColor(deviceContext, colorState->mTextColor);
  (void)::SetBkColor(deviceContext, colorState->mBackgroundColor);
}

