/**
 * Address: 0x004D5080 (FUN_004D5080)
 *
 * What it does:
 * Runs one introspective sort lane for triple-string records: quick-partition
 * while depth budget remains, then heap/insertion fallback by range size.
 */
std::int32_t wxIntroSortTripleMsvc8StringRecordRangeRuntime(
  Msvc8TripleStringRecordRuntimeView* first,
  Msvc8TripleStringRecordRuntimeView* last,
  std::int32_t depthBudget
)
{
  std::int32_t recordCount = static_cast<std::int32_t>(last - first);
  while (recordCount > 32) {
    if (depthBudget <= 0) {
      if (recordCount > 1) {
        wxMakeHeapTripleMsvc8StringRecordRangeRuntime(first, last);
      }
      return wxSortHeapTripleMsvc8StringRecordRangeRuntime(first, last);
    }

    WxTripleStringPartitionRuntimeResult cut{};
    (void)wxPartitionTripleMsvc8StringRecordRangeRuntime(&cut, first, last);

    const std::int32_t halfDepth = depthBudget / 2;
    depthBudget = halfDepth + (halfDepth / 2);

    const std::int32_t leftCount = static_cast<std::int32_t>(cut.leftRangeEnd - first);
    const std::int32_t rightCount = static_cast<std::int32_t>(last - cut.rightRangeBegin);
    if (leftCount < rightCount) {
      (void)wxIntroSortTripleMsvc8StringRecordRangeRuntime(first, cut.leftRangeEnd, depthBudget);
      first = cut.rightRangeBegin;
    } else {
      (void)wxIntroSortTripleMsvc8StringRecordRangeRuntime(cut.rightRangeBegin, last, depthBudget);
      last = cut.leftRangeEnd;
    }

    recordCount = static_cast<std::int32_t>(last - first);
  }

  if (recordCount > 1) {
    wxInsertionSortTripleMsvc8StringRecordRangeRuntime(first, last);
  }

  return recordCount;
}

