/**
 * Address: 0x009C7E90 (FUN_009C7E90)
 *
 * What it does:
 * Queries Win32 work-area rectangle and writes x/y/width/height lanes to the
 * provided output pointers.
 */
std::int32_t* wxGetDesktopWorkAreaXywh(
  std::int32_t* const outX,
  std::int32_t* const outY,
  std::int32_t* const outWidth,
  std::int32_t* const outHeight
) noexcept
{
  RECT workArea{};
  (void)::SystemParametersInfoW(SPI_GETWORKAREA, 0, &workArea, 0);

  if (outX != nullptr) {
    *outX = workArea.left;
  }
  if (outY != nullptr) {
    *outY = workArea.top;
  }
  if (outWidth != nullptr) {
    *outWidth = workArea.right - workArea.left;
  }
  if (outHeight != nullptr) {
    *outHeight = workArea.bottom - workArea.top;
  }

  return outHeight;
}

