/**
 * Address: 0x00A02930 (FUN_00A02930)
 *
 * What it does:
 * Closes one active Win32 find handle lane with `FindClose` and resets the
 * stored slot to `INVALID_HANDLE_VALUE`.
 */
HANDLE wxFindCloseAndInvalidateHandleSlot(
  HANDLE* const findHandleSlot
) noexcept
{
  if (findHandleSlot == nullptr) {
    return INVALID_HANDLE_VALUE;
  }

  HANDLE result = *findHandleSlot;
  if (result != INVALID_HANDLE_VALUE) {
    result = reinterpret_cast<HANDLE>(static_cast<std::intptr_t>(::FindClose(result)));
    *findHandleSlot = INVALID_HANDLE_VALUE;
  }
  return result;
}

/**
 * Address: 0x00A02950 (FUN_00A02950)
 *
 * What it does:
 * Thunk adapter preserving `wxFindCloseAndInvalidateHandleSlot(...)`
 * argument/return lanes.
 */
HANDLE wxFindCloseAndInvalidateHandleSlotThunk(
  HANDLE* const findHandleSlot
) noexcept
{
  return wxFindCloseAndInvalidateHandleSlot(findHandleSlot);
}


