  [[nodiscard]] std::uint32_t wxArrayStringAddOneSharedTextRuntime(
    WxArrayStringAddRuntimeView* const arrayRuntime,
    const wxStringRuntime* const sourceText
  ) noexcept
  {
    wxStringRuntime retainedText{};
    retainedText.m_pchData = nullptr;
    RetainRuntimeStringFromPointerStorage(&retainedText, sourceText);
    const wchar_t* const addedText = retainedText.m_pchData != nullptr ? retainedText.m_pchData : wxEmptyString;

    std::uint32_t insertionIndex = arrayRuntime->itemCount;
    if (arrayRuntime->autoSort != 0u && arrayRuntime->itemCount != 0u) {
      std::uint32_t lowerBound = 0u;
      std::uint32_t upperBound = arrayRuntime->itemCount;
      while (lowerBound < upperBound) {
        const std::uint32_t mid = (upperBound + lowerBound) >> 1u;
        const wchar_t* const candidate =
          (arrayRuntime->itemStorage != nullptr && arrayRuntime->itemStorage[mid] != nullptr)
          ? arrayRuntime->itemStorage[mid]
          : wxEmptyString;
        const std::int32_t compare = std::wcscmp(addedText, candidate);
        if (compare < 0) {
          upperBound = mid;
        } else if (compare > 0) {
          lowerBound = mid + 1u;
        } else {
          lowerBound = mid;
          break;
        }
      }
      insertionIndex = lowerBound;
    }

    WxDwordArrayEnsureAppendCapacity(
      reinterpret_cast<WxDwordArrayRuntimeView*>(arrayRuntime),
      1u
    );
    std::memmove(
      arrayRuntime->itemStorage + insertionIndex + 1u,
      arrayRuntime->itemStorage + insertionIndex,
      sizeof(wchar_t*) * static_cast<std::size_t>(arrayRuntime->itemCount - insertionIndex)
    );
    arrayRuntime->itemStorage[insertionIndex] = const_cast<wchar_t*>(addedText);
    arrayRuntime->itemCount += 1u;
    return insertionIndex;
  }


