  [[nodiscard]] bool wxIsDotOrDotDotEntryName(
    const wchar_t* const name
  ) noexcept
  {
    if (name == nullptr || name[0] != L'.') {
      return false;
    }

    return name[1] == L'\0' || (name[1] == L'.' && name[2] == L'\0');
  }
