      if (std::iswalpha(static_cast<wint_t>(buffer[0])) != 0
          && buffer.size() > 1 && buffer[1] == L':') {
        AssignOwnedWxString(outValue, std::wstring(1, buffer[0]) + L":.");
        return outValue;
      }
