  void wxTreeListBroadcastStateByteRecursive(
    const void* const ownerRuntime,
    const int stateValue
  ) noexcept
  {
    const auto* const owner = static_cast<const WxTreeListOwnerRuntimeView*>(ownerRuntime);
    for (WxTreeListLinkRuntimeView* link = (owner != nullptr) ? owner->firstLink : nullptr;
         link != nullptr;
         link = link->next) {
      WxTreeListNodeRuntimeView* const node = link->node;
      if (WxSizerItemHasWindow(reinterpret_cast<const WxSizerItemLayoutRuntimeView*>(node)) != FALSE) {
        void* const target = node->directDispatchTarget;
        auto* const vtable = *reinterpret_cast<WxTreeDispatchTargetVTableRuntimeView**>(target);
        if (vtable != nullptr && vtable->dispatchState != nullptr) {
          vtable->dispatchState(target, stateValue);
        }
      } else if (WxSizerItemHasSizer(reinterpret_cast<const WxSizerItemLayoutRuntimeView*>(node)) != FALSE) {
        wxTreeListBroadcastStateByteRecursive(node->childBranch, stateValue);
      }
    }
  }


