  int wxFillDwordRangeFromScalarCoreRuntime(
    std::uint32_t* destination,
    const int count,
    const std::uint32_t* const sourceValue
  ) noexcept
  {
    std::uint32_t remaining = static_cast<std::uint32_t>(count);
    while (remaining != 0u)
    {
      *destination = *sourceValue;
      ++destination;
      --remaining;
    }
    return static_cast<int>(remaining);
  }

